import { expect, Page } from '@playwright/test';

/**
 * Page Object — Shop · Zennx Demo Store.
 * https://zennx.dev/demo-ecommerse
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 */
export class DemoEcommersePage {
    readonly page: Page;

    private readonly navSignup = () => this.page.getByTestId('nav-signup');
    private readonly shopTheQaCollectionHeading = () => this.page.getByRole('heading', { name: 'Shop the QA collection' });
    private readonly welcomeTestYourAccountIsReady = () => this.page.getByRole('status');

    constructor(page: Page) {
        this.page = page;
    }

    /** Open this page directly. */
    async goto(): Promise<void> {
        await this.page.goto('https://zennx.dev/demo-ecommerse');
    }

    async clickNavSignup(): Promise<void> {
        await this.navSignup().click();
    }

    async expectShopTheQaCollectionHeadingVisible(): Promise<void> {
        await expect(this.shopTheQaCollectionHeading()).toBeVisible();
    }

    async expectWelcomeTestYourAccountIsReadyText(expected: string | RegExp): Promise<void> {
        await expect(this.welcomeTestYourAccountIsReady()).toContainText(expected);
    }
}
